156							settings)) {
157			perror("gpiod_line_config_add_line_settings");
158			goto out;
159		}
160	
161		req_cfg = gpiod_request_config_new();
162		if (!req_cfg) {
163			perror("gpiod_request_config_new");
164			goto out;
165		}
166		gpiod_request_config_set_consumer(req_cfg, CONSUMER);
167	
168		req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
169		if (!req) {
170			perror("gpiod_chip_request_lines (line busy or no permission?)");
171			goto out;
