196			int pr = poll(&pfd, 1, POLL_MS);
197	
198			if (pr < 0) {
199				if (errno == EINTR)
200					continue; /* signal: loop re-checks the flag */
201				perror("poll");
202				goto out;
203			}
204			if (pr == 0)
