/*
 * sensors.h - the doorway sensor table and helpers that need no hardware.
 *
 * Everything here is pure (no GPIO access), so it can be unit-tested on
 * any machine. sensortest.c does the actual libgpiod work.
 */
#ifndef SENSORS_H
#define SENSORS_H

#include <gpiod.h>
#include <stddef.h>

enum sensor_kind {
	SENSOR_BEAM, /* IR break-beam receiver behind a 100k/100k divider */
	SENSOR_REED, /* magnetic reed switch, dry contact to ground */
};

struct sensor {
	const char *name;      /* short label printed on every event line */
	unsigned int offset;   /* BCM GPIO number == line offset on gpiochip0 */
	unsigned int pin;      /* physical header pin, for humans wiring it */
	enum sensor_kind kind;
};

extern const struct sensor sensors[];
extern const size_t num_sensors;

/* Return the sensor wired to this line offset, or NULL if none is. */
const struct sensor *sensor_by_offset(unsigned int offset);

/* Pull bias the line needs for this kind of sensor. */
enum gpiod_line_bias sensor_bias(enum sensor_kind kind);

/* Human-readable state for a raw line level (high = 1, low = 0). */
const char *sensor_state_name(enum sensor_kind kind, int high);

#endif /* SENSORS_H */

