					      GPIOD_LINE_DIRECTION_INPUT) ||
	    gpiod_line_settings_set_edge_detection(settings,
						   GPIOD_LINE_EDGE_BOTH) ||
	    gpiod_line_settings_set_event_clock(settings,
						GPIOD_LINE_CLOCK_MONOTONIC)) {
		perror("gpiod_line_settings_set_*");
		goto out;
	}

