	if (print_initial_states(req) < 0)
		goto out;

	struct pollfd pfd = {
		.fd = gpiod_line_request_get_fd(req),
		.events = POLLIN,
	};

	while (!stop_requested) {
		int pr = poll(&pfd, 1, POLL_MS);

		if (pr < 0) {
			if (errno == EINTR)
				continue; /* signal: loop re-checks the flag */
			perror("poll");
			goto out;
		}
