/*
 * sensors.c - doorway sensor table and hardware-free helpers.
 */
#include "sensors.h"

const struct sensor sensors[] = {
	{ "beam1", 17u, 11u, SENSOR_BEAM },
	{ "beam2", 22u, 15u, SENSOR_BEAM },
	{ "door",  27u, 13u, SENSOR_REED },
};

const size_t num_sensors = sizeof(sensors) / sizeof(sensors[0]);

const struct sensor *sensor_by_offset(unsigned int offset)
{
	for (size_t i = 0; i < num_sensors; i++) {
		if (sensors[i].offset == offset)
			return &sensors[i];
	}
	return NULL;
}

enum gpiod_line_bias sensor_bias(enum sensor_kind kind)
{
	switch (kind) {
	case SENSOR_BEAM:
		/* An internal pull would shift the external divider voltage. */
		return GPIOD_LINE_BIAS_DISABLED;
	case SENSOR_REED:
		/* The switch only shorts to ground; the pull-up supplies HIGH. */
		return GPIOD_LINE_BIAS_PULL_UP;
	}
	return GPIOD_LINE_BIAS_DISABLED;
}

const char *sensor_state_name(enum sensor_kind kind, int high)
{
	switch (kind) {
	case SENSOR_BEAM:
		return high ? "clear" : "blocked";
	case SENSOR_REED:
		/* Magnet near closes the switch, pulling the line LOW. */
		return high ? "open" : "closed";
	}
	return "unknown";
}

