static void format_wall_time(char *buf, size_t size)
{
	struct timespec ts;
	struct tm tm;
	char secs[32];

	clock_gettime(CLOCK_REALTIME, &ts);
	localtime_r(&ts.tv_sec, &tm);
	strftime(secs, sizeof(secs), "%Y-%m-%d %H:%M:%S", &tm);
	snprintf(buf, size, "%s.%03ld", secs, ts.tv_nsec / 1000000L);
